func (s *BufferedWriteSyncer) Stop() (err error) {


	stopped := func() bool {
		s.mu.Lock()
		defer s.mu.Unlock()

		if !s.initialized {
			return false
		}

		if s.stopped {
			return false
		}
		s.stopped = true

		s.ticker.Stop()
		close(s.stop) 
		return true
	}()


	if !stopped {
		return
	}



	<-s.done

	return s.Sync()
}

