func (c *counter) IncCheckReset(t time.Time, tick time.Duration) uint64 {

	tn := t.UnixNano()
	resetAfter := c.resetAt.Load()
	if resetAfter > tn {
		return c.counter.Add(1)
	}

	c.counter.Store(1)

	newResetAfter := tn + tick.Nanoseconds()
	if !c.resetAt.CompareAndSwap(resetAfter, newResetAfter) {


		return c.counter.Add(1)
	}

	return 1
}

